import { cookies, headers } from 'next/headers'

export default async function Home() {
  const [cookieStore, headerStore] = await Promise.all([cookies(), headers()])
  const theme = cookieStore.get('theme')?.value ?? 'light'
  const acceptLanguage = headerStore.get('accept-language')
  const language = acceptLanguage
    ?.split(',')
    .map((entry) => {
      const [tag, quality] = entry.trim().split(';q=')
      return { tag, weight: quality === undefined ? 1 : Number(quality) }
    })
    .filter(({ tag, weight }) => tag && Number.isFinite(weight) && weight > 0 && weight <= 1)
    .sort((a, b) => b.weight - a.weight)[0]?.tag ?? 'Not specified'

  return (
    <main>
      <h1>User Preferences</h1>
      <p>Current theme: {theme}</p>
      <p>Preferred language: {language}</p>
    </main>
  )
}

